"""Explain API comment mismatch and hash collision, mask and rotation basics."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1925': ('안내문에는 예전 창구 이름이 남아 있어도 실제 창구 이름을 확인해야 해요. 코드에서도 설명의 이름과 실제 선언을 대조해요.', '주석의 evict 이름과 실제 put 함수, 참조 반환 약속을 구별합니다.', 'GET 성공 두 번 → 보관 권리 2개 → put 두 번으로 반환을 적으세요. 중간 fetch 횟수는 반환 횟수에 더하지 않아요.', ['헤더는 함수 이름과 입력·출력 약속을 적어 다른 코드가 사용할 수 있게 하는 파일이에요. 여기에는 실제 공개 함수로 void stack_depot_put(depot_stack_handle_t handle)이 선언돼 있어요. put은 GET으로 확보한 보관 권리를 하나 돌려주는 함수예요.', '이 고정 버전의 설명 주석에는 호출 수를 셀 때 stack_depot_evict라는 다른 이름이 남아 있어요. evict는 기록을 내보낸다는 뜻의 말이에요. 하지만 바로 아래 선언과 실제 lib/stackdepot.c 구현 이름은 stack_depot_put이에요. 주석에 나온 이름만 복사해서 새 호출 예제를 만들면 안 돼요.', '함수 선언은 이름과 인수의 형태를 알려 주고 구현 본문은 실제 수행 순서를 보여 줘요. 설명 문장도 유용하지만 이름이 어긋나면 이 두 근거를 함께 확인해요. 이 수업은 과거 이름처럼 남은 표현을 현재 함수가 두 개 있다는 뜻으로 읽지 않아요.', '정상 참조 관리 예에서 GET 저장을 두 번 성공하면 같은 기록을 보관할 권리가 둘일 수 있어요. 다른 변화가 없다면 put 한 번으로 2에서 1, 다시 한 번으로 1에서 0이 돼요. 마지막 반환일 때 검색 목록에서 빼고 재사용 대기로 보내요.', 'fetch는 배열 주소와 항목 수를 읽는 함수이며 보관 권리를 추가하지 않아요. 두 GET 사이에 fetch를 세 번 했다고 put을 다섯 번 해야 하는 것이 아니에요. 반환 횟수는 단순 조회 횟수가 아니라 실제로 확보한 참조에 맞춰요.', '마지막 반환 뒤에도 번호 숫자가 변수에 남을 수 있지만 사용 권리는 끝났어요. 옛 번호나 빌린 배열 주소를 계속 쓰지 않아요. 주석의 단어보다 어떤 함수가 권리를 얻고 어떤 함수가 돌려주는지 흐름으로 이해하면 이름의 흔적에 덜 헷갈려요.'], [('이 버전에서 실제로 선언되고 구현된 공개 참조 반환 함수의 이름은 무엇인가요?', ['stack_depot_evict만 있어요', 'stack_depot_put이에요'], '정답은 두 번째예요. 헤더 선언과 구현 본문에서 put을 확인할 수 있어요. 주석에 남은 다른 이름을 그대로 실제 호출 이름으로 쓰면 안 돼요.'), ('참조 반환 횟수를 맞추는 올바른 기준은 무엇인가요?', ['GET으로 확보한 권리와 put으로 돌려주는 권리를 맞춰요', 'fetch를 할 때마다 무조건 메모리를 해제해요'], '정답은 첫 번째예요. fetch는 조회이며 참조를 새로 얻지 않아요. 보관 권리의 획득과 반환을 짝지어 마지막 권리가 끝나는 시점을 관리해요.')]), 'os1926': ('책 제목을 짧은 번호로 분류하면 찾기 쉬워요. 하지만 같은 번호 칸에 다른 책도 들어갈 수 있어서 실제 제목을 다시 확인해야 해요.', '32비트 해시의 충돌과 실제 내용 비교가 필요한 이유를 이해합니다.', '칸이 4개인데 서로 다른 카드가 5장이면 적어도 한 칸에 두 장이 들어간다는 그림을 그리세요.', ['key는 찾으려는 원래 자료예요. 글자열이나 호출 위치 배열 같은 것이 key가 될 수 있어요. jhash는 key를 계산해서 32비트 hash라는 요약 숫자를 만들어요. 해시 테이블은 이 숫자를 이용해 찾아볼 후보 범위를 줄이는 자료구조예요.', '32비트에는 0과 1을 넣는 자리가 32개 있어 가능한 값은 2의 32승인 4294967296가지예요. 많아 보여도 끝이 있는 수예요. 긴 입력으로 만들 수 있는 서로 다른 key는 이 수보다 많을 수 있으므로 모두 다른 요약 숫자를 받게 할 수는 없어요.', '작은 예로 칸 4개에 서로 다른 카드 5장을 넣는다고 해요. 어떤 방법을 쓰든 적어도 한 칸에는 두 장 이상 들어가요. 해시도 서로 다른 key가 같은 요약 숫자를 받는 일이 가능하며 이를 충돌이라고 해요. 이 그림은 원리 예시이지 실제 jhash 충돌 입력을 계산한 결과는 아니에요.', '따라서 hash가 같으면 같은 후보일 수 있다는 뜻이지 내용이 반드시 같다는 뜻은 아니에요. stack depot은 hash와 항목 수가 맞은 뒤 호출 위치 배열을 실제로 비교해요. 같은 hash를 가진 [10,20]과 [10,30]이라면 내용 비교에서 구별돼요.', 'key·hash·bucket 번호도 구별해요. key는 원본, hash는 32비트 요약, bucket은 실제 표에서 찾아볼 칸이에요. 표가 작으면 서로 다른 hash도 같은 bucket에 들어갈 수 있어요. 요약 숫자 충돌과 표의 같은 칸 배정은 관련 있지만 같은 조건은 아니에요.', '이 함수의 원문 목적은 해시 테이블 검색이에요. 요약값 하나가 원본의 고유 신분증이 되거나 원본을 복원하는 암호문이 되는 것은 아니에요. 내용을 합쳐 저장할 때는 이 검색 도구 뒤에 실제 동등성 검사를 연결해야 해요.'], [('두 긴 key의 32비트 hash가 같으면 원래 내용도 반드시 같나요?', ['네. 32비트가 모든 긴 자료를 고유하게 구분해요', '아니요. 충돌할 수 있으므로 실제 내용도 비교해야 해요'], '정답은 두 번째예요. 원래 자료의 가능한 종류가 요약 숫자의 종류보다 많을 수 있어요. 칸보다 카드가 많으면 같은 칸을 나눠 쓰듯 서로 다른 내용이 같은 hash를 받을 수 있어요.'), ('stack depot이 hash를 확인한 뒤 호출 위치 배열까지 비교하는 이유는 무엇인가요?', ['서로 다른 내용이 같은 hash를 받은 경우를 구별하려고요', '모든 hash를 암호문으로 바꾸려고요'], '정답은 첫 번째예요. 요약 숫자는 후보를 줄이고 배열 비교는 실제 일치를 확인해요. 이 비교는 암호화 과정이 아니에요.')]), 'os1927': ('칸이 16개인 표의 번호는 0부터 15까지예요. 칸 개수와 마지막 번호가 하나 차이 나는 이유를 비트 계산에서도 사용해요.', '2의 거듭제곱 크기와 mask로 칸을 고르는 원리를 이해합니다.', 'n=4 → 크기 16 → mask 15를 적으세요. 31의 이진수 11111에서 아래 네 자리 1111을 남기면 번호 15예요.', ['jhash_size(n)은 32비트 부호 없는 정수 1을 왼쪽으로 n칸 이동하는 매크로예요. 매크로는 컴파일 전에 식으로 펼쳐지는 규칙이에요. 유효한 범위에서 한 칸 이동할 때마다 두 배가 되므로 결과는 2의 n승이에요.', 'n=4이면 1→2→4→8→16이에요. 여기서 4는 칸 개수 자체가 아니라 두 배로 만드는 횟수, 즉 지수 또는 order예요. jhash_size(4)가 4개짜리 배열을 만든다는 뜻도 아니에요. 이 식은 크기 숫자 16을 계산해요.', 'jhash_mask(n)은 계산한 크기에서 1을 빼요. 크기 16이면 mask는 15예요. 15를 이진수로 쓰면 1111이라 아래 네 비트만 1이고 나머지는 0이에요. 비트 AND인 &는 두 값의 같은 자리에서 둘 다 1일 때만 1을 남겨요.', 'hash가 31이면 이진수 11111이고 mask 15는 01111이에요. 둘을 AND하면 01111인 15가 돼요. 0~15 사이만 남으므로 16칸 표의 범위를 벗어나지 않아요. 이는 부호 없는 값에서 16으로 나눈 나머지와 같아요.', '이 규칙은 표 크기가 2의 거듭제곱일 때 써요. 크기 10에 mask 9를 쓰면 같은 원리로 나머지를 구할 수 없어요. 예를 들어 6 & 9는 0이지만 6을 10으로 나눈 나머지는 6이에요. 단순히 크기에서 1을 뺐다고 모든 표에 맞는 것은 아니에요.', 'n은 이 u32 이동에서 0부터 31까지의 범위를 지켜요. 이 매크로에는 잘못된 이동 횟수를 거절하는 검사가 없어요. n=0이면 크기 1·mask 0이고 모든 hash가 0번 칸으로 가요. 32칸 이동 같은 잘못된 값을 실제 실험으로 실행하지 않아요.'], [('jhash_size(4)가 계산하는 크기는 얼마인가요?', ['4예요', '16이에요'], '정답은 두 번째예요. 1을 네 번 두 배로 하면 16이에요. 입력 4는 결과 칸 수가 아니라 거듭제곱의 단계예요.'), ('16칸 표의 번호를 고를 때 쓰는 mask는 무엇인가요?', ['15예요', '16이에요'], '정답은 첫 번째예요. 16-1=15이며 이진수 1111로 아래 네 비트를 남겨요. 16 자체를 쓰면 같은 네 자리 범위를 고를 수 없어요.')]), 'os1928': ('시계가 끝 숫자를 지나 처음으로 돌아오듯, 정해진 자리 수의 부호 없는 정수도 끝을 넘으면 처음으로 돌아와요. 비트를 돌리는 동작은 줄 끝의 종이를 앞에 다시 붙이는 것과 비슷해요.', 'u32의 순환 산술과 비트 회전·XOR를 구별합니다.', '네 자리 예 1001을 왼쪽 한 칸 회전하면 0011, 이동만 하면 0010이라고 그리세요. 실제 함수는 32자리라는 점도 적으세요.', ['Jenkins hash는 a·b·c라는 세 u32 값을 섞어 요약값을 만들어요. u32는 부호 없는 32비트 정수라 0부터 4294967295까지 나타내요. 음수를 저장하는 signed 정수와 구별해요.', '이 범위에서 가장 큰 값에 1을 더하면 0으로 돌아오고, 0에서 1을 빼면 가장 큰 값으로 돌아와요. 이를 2의 32승 모듈러 산술이라고 해요. 모듈러는 일정 크기로 한 바퀴 돌고 남은 값을 사용한다는 뜻이에요. 이 코드의 unsigned 계산 규칙이며 signed 범위 초과에도 같은 C 언어 보장이 있다고 생각하면 안 돼요.', 'rol32는 32비트를 왼쪽으로 회전시켜요. 왼쪽 끝으로 나간 비트를 오른쪽 끝으로 돌려 넣어요. 이해하기 쉬운 네 비트 예에서 1001을 한 칸 회전하면 0011이에요. 그냥 왼쪽으로 이동하고 네 자리만 남기면 0010이어서 결과가 달라요.', '실제 32비트 예로 맨 왼쪽과 맨 오른쪽만 1인 값을 한 칸 회전하면 오른쪽 두 자리가 1인 값 3이 돼요. 일반 왼쪽 이동 결과를 u32로 남기면 값 2예요. 회전은 끝에서 나간 1을 버리지 않고 다시 붙였기 때문에 1만큼 차이가 나요.', 'XOR인 ^는 같은 자리의 두 비트가 다르면 1, 같으면 0을 만들어요. 그래서 0^0과 1^1은 0, 0^1과 1^0은 1이에요. __jhash_mix는 빼기·회전·XOR·더하기를 순서대로 수행해 한 값의 여러 자리가 다른 값에 영향을 주게 해요.', '덧셈의 올림도 자리를 서로 연결해요. 네 비트 그림에서 0111에 0001을 더하면 1000이 되어 여러 자리가 바뀌어요. 이 예들은 사용한 연산의 원리를 설명하며 실제 hash의 분포나 암호학적 안전성을 증명하는 시험은 아니에요. 정확한 결과를 재현하려면 원문의 타입과 연산 순서를 유지해요.'], [('이 코드에서 u32 덧셈이 표현 범위를 넘으면 어떤 계산 규칙을 쓰나요?', ['언제나 signed 정수의 정의되지 않은 범위 초과와 같아요', '2의 32승을 기준으로 순환하는 부호 없는 정수 계산이에요'], '정답은 두 번째예요. u32는 unsigned 타입이므로 최대값 다음은 0으로 돌아와요. 타입을 signed로 바꿔도 같은 보장을 받는다고 가정하면 안 돼요.'), ('왼쪽 회전이 일반 왼쪽 이동과 다른 점은 무엇인가요?', ['왼쪽 끝으로 나간 비트를 오른쪽 끝에 다시 붙여요', '언제나 모든 비트를 0으로 만들어요'], '정답은 첫 번째예요. 회전은 원을 따라 자리를 바꾸듯 끝 비트를 반대쪽으로 옮겨요. 네 자리 1001의 한 칸 회전은 0011이며 모두 0이 되지 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_477.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
